module benchmark/solution

type State = Idle(int) | Moving(int, int) | DoorOpen(int, int)
type Event = Call(int) | Tick | Arrive

pure func transition(state: State, event: Event) -> State =
  match state {
    Idle(floor) => match event {
      Call(target) => if target == floor then DoorOpen(floor, 3) else Moving(floor, target),
      Tick => state,
      Arrive => state
    },
    Moving(cur, target) => match event {
      Call(_) => state,
      Tick => Moving(cur, target),
      Arrive => DoorOpen(target, 3)
    },
    DoorOpen(floor, timer) => match event {
      Call(_) => state,
      Tick => if timer > 1 then DoorOpen(floor, timer - 1) else Idle(floor),
      Arrive => state
    }
  }

pure func display(state: State) -> string =
  match state {
    Idle(floor) => "IDLE @ floor ${floor}",
    Moving(cur, target) => "MOVING ${cur} -> ${target}",
    DoorOpen(floor, timer) => "DOOR_OPEN @ floor ${floor} (${timer}sec)"
  }

func simulate(state: State, events: [Event]) -> () ! {IO} =
  match events {
    [] => (),
    event :: rest => {
      let next = transition(state, event);
      println(display(next));
      simulate(next, rest)
    }
  }

export func main() -> () ! {IO} =
  simulate(Idle(1), [Call(5), Tick, Tick, Arrive, Tick, Tick, Tick, Tick, Call(1)])

